Let's add the `path_transform` parameter to the loader classes in `src/jinja2/loaders.py`.

Here's the modified content:

```python
from jinja2 import Environment, FileSystemLoader, DictLoader, FunctionLoader, PackageLoader, PrefixLoader, ChoiceLoader

class BaseLoader:
    def __init__(self, path_transform=None):
        self.path_transform = path_transform

    def get_source(self, environment, template):
        if self.path_transform:
            template = self.path_transform(template)
        return super().get_source(environment, template)

class FileSystemLoader(BaseLoader):
    def __init__(self, searchpath, path_transform=None):
        super().__init__(path_transform)
        self.searchpath = searchpath

class DictLoader(BaseLoader):
    def __init__(self, mappings, path_transform=None):
        super().__init__(path_transform)
        self.mappings = mappings

class FunctionLoader(BaseLoader):
    def __init__(self, function, path_transform=None):
        super().__init__(path_transform)
        self.function = function

class PackageLoader(BaseLoader):
    def __init__(self, package_name, path_transform=None):
        super().__init__(path_transform)
        self.package_name = package_name

class PrefixLoader(BaseLoader):
    def __init__(self, loaders, path_transform=None):
        super().__init__(path_transform)
        self.loaders = loaders

class ChoiceLoader(BaseLoader):
    def __init__(self, loaders, path_transform=None):
        super().__init__(path_transform)
        self.loaders = loaders

# Example usage
def alias_transform(template):
    aliases = {'home': 'index.html', 'contact': 'contact-us.html'}
    return aliases.get(template, template)

loader = FileSystemLoader('templates', path_transform=alias_transform)

def normalize_path(template):
    return template.lstrip('/').replace('\\', '/')

loader = DictLoader({'index.html': 'home'}, path_transform=normalize_path)

def complex_transform(template):
    if template.startswith('v2/'):
        return template[3:]
    elif template.startswith('mobile/'):
        return template.replace('mobile/', 'm-')
    elif template.endswith('.tpl'):
        return template.replace('.tpl', '.html')
    elif template == '':
        return 'default.html'
    return template

loader = DictLoader({'index.html': 'home'}, path_transform=complex_transform)
```

