import unittest
from jinja2 import Environment, FileSystemLoader, DictLoader, FunctionLoader, PackageLoader, PrefixLoader, ChoiceLoader

class TestLoaders(unittest.TestCase):
    def test_file_system_loader(self):
        loader = FileSystemLoader('templates', path_transform=lambda x: x.upper())
        env = Environment(loader=loader)
        template = env.get_template('index.html')
        self.assertEqual(template.name, 'INDEX.HTML')

    def test_dict_loader(self):
        loader = DictLoader({'index.html': 'home'}, path_transform=lambda x: x.lower())
        env = Environment(loader=loader)
        template = env.get_template('index.html')
        self.assertEqual(template.name, 'home')

    def test_function_loader(self):
        loader = FunctionLoader(lambda x: x + '_transformed', path_transform=lambda x: x.upper())
        env = Environment(loader=loader)
        template = env.get_template('index.html')
        self.assertEqual(template.name, 'INDEX_TRANSFORMED')

    def test_package_loader(self):
        loader = PackageLoader('my_package', path_transform=lambda x: x.lower())
        env = Environment(loader=loader)
        template = env.get_template('index.html')
        self.assertEqual(template.name, 'index.html')

    def test_prefix_loader(self):
        loader = PrefixLoader({
            'sub1': FileSystemLoader('sub1/templates', path_transform=lambda x: x.upper()),
            'sub2': DictLoader({'index.html': 'home'}, path_transform=lambda x: x.lower())
        }, path_transform=lambda x: x.lower())
        env = Environment(loader=loader)
        template = env.get_template('sub1/index.html')
        self.assertEqual(template.name, 'SUB1/INDEX.HTML')

    def test_choice_loader(self):
        loader = ChoiceLoader([
            FileSystemLoader('templates', path_transform=lambda x: x.upper()),
            DictLoader({'index.html': 'home'}, path_transform=lambda x: x.lower())
        ], path_transform=lambda x: x.lower())
        env = Environment(loader=loader)
        template = env.get_template('index.html')
        self.assertEqual(template.name, 'home')

if __name__ == '__main__':
    unittest.main()
